const report = { started_at: new Date().toISOString(), baseURL, implementation: 'Real production React/Vite assets, Chromium layout, keyboard, focus, URL and network behavior.', mocked: 'All /api/ requests, two synthetic books, model responses, material evidence, proposal writes, workflow and image jobs. No API request reaches the backend.', unverified: ['Real model generation quality/latency', 'Filesystem write correctness and real third-party material evidence', 'Touch hardware and non-Chromium browser behavior'], checks: [], screenshots: [], unknown_api: [], page_errors: [] };
