let browser;
async function check(name, body) { if(process.env.WORKBENCH_ACCEPTANCE_FILTER && !new RegExp(process.env.WORKBENCH_ACCEPTANCE_FILTER).test(name)) return; const begin=Date.now(); try {const detail=await body(); report.checks.push({name,status:'passed',ms:Date.now()-begin,...detail});console.log(`PASS ${name}`)} catch(error) {report.checks.push({name,status:'failed',ms:Date.now()-begin,error:String(error.stack||error)});console.log(`FAIL ${name}: ${error.message}`)} }
async function pageWithFixtures(state=createFixtureState(), viewport={width:1440,height:1000}) {
 const page=await browser.newPage({viewport, reducedMotion:'reduce'});page.setDefaultTimeout(6500);
 if(fixtureDist){
  if(!fixtureDist.startsWith(root+path.sep)||!fs.existsSync(path.join(fixtureDist,'index.html')))throw new Error('Acceptance assets must be an existing production dist within this workspace');
  const contentTypes={'.html':'text/html','.js':'application/javascript','.css':'text/css','.json':'application/json','.svg':'image/svg+xml','.png':'image/png','.jpg':'image/jpeg','.woff2':'font/woff2','.woff':'font/woff','.ico':'image/x-icon'};
  await page.route('**/*',async route=>{
   const url=new URL(route.request().url());if(url.origin!==new URL(baseURL).origin)return route.abort();
   const requested=path.resolve(fixtureDist,decodeURIComponent(url.pathname).replace(/^\/+/,''));
   if(requested!==fixtureDist&&!requested.startsWith(fixtureDist+path.sep))return route.fulfill({status:400,body:'Invalid asset path'});
   const file=fs.existsSync(requested)&&fs.statSync(requested).isFile()?requested:path.extname(requested)?null:path.join(fixtureDist,'index.html');
   if(!file)return route.fulfill({status:404,body:'Fixture asset missing'});
   return route.fulfill({status:200,contentType:contentTypes[path.extname(file)]||'application/octet-stream',body:fs.readFileSync(file)});
  });report.asset_source={kind:'isolated route fulfillment; no listener',dist:fixtureDist};
 }
 const fixture=await installFixtures(page,{state});page.on('pageerror', error=>report.page_errors.push({url:page.url(),error:String(error)}));page.on('close',()=>report.unknown_api.push(...state.unknown));return {page,...fixture};
}
async function open(page, url, heading) {await page.goto(baseURL+url,{waitUntil:'domcontentloaded'});if(heading)await page.getByRole('heading',{name:heading,exact:true}).first().waitFor();await sleep(200);}
